import{j as e,d as s,H as i,F as r}from"./index-DvQDi8s_-drv-seo-v15-20261106.js";const d=[{title:"Quem somos",paragraphs:["O endereço do nosso site é: https://drvcertificacoes.com.br."]},{title:"Comentários",paragraphs:["Quando os visitantes deixam comentários no site, coletamos os dados exibidos no formulário de comentários, além do endereço IP do visitante e da identificação do navegador (user agent), para auxiliar na detecção de spam.","Uma sequência anonimizada de caracteres criada a partir do seu endereço de e-mail (também chamada de hash) poderá ser fornecida ao serviço Gravatar para verificar se você o utiliza. A política de privacidade do Gravatar está disponível em: https://automattic.com/privacy/. Após a aprovação do comentário, sua foto de perfil ficará visível publicamente no contexto do seu comentário."]},{title:"Mídia",paragraphs:["Se você enviar imagens para o site, evite fazer upload de imagens que contenham dados de localização incorporados (EXIF GPS). Os visitantes do site podem baixar e extrair quaisquer dados de localização presentes nas imagens publicadas."]},{title:"Cookies",paragraphs:["Se você deixar um comentário em nosso site, poderá optar por salvar seu nome, endereço de e-mail e site em cookies. Isso é para sua conveniência, para que você não precise preencher seus dados novamente ao deixar outro comentário. Esses cookies permanecerão armazenados por um ano.","Se você visitar nossa página de login, um cookie temporário será definido para determinar se o seu navegador aceita cookies. Esse cookie não contém dados pessoais e será descartado quando você fechar o navegador.",'Ao fazer login, também configuraremos diversos cookies para salvar suas informações de acesso e suas preferências de exibição de tela. Os cookies de login duram dois dias, e os cookies de opções de tela duram um ano. Se você selecionar a opção "Lembrar-me", seu login permanecerá ativo por duas semanas. Ao sair da sua conta, os cookies de login serão removidos.',"Se você editar ou publicar um artigo, um cookie adicional será salvo em seu navegador. Esse cookie não contém dados pessoais e apenas indica o ID da publicação que você acabou de editar. Ele expira após 1 dia."]},{title:"Conteúdo incorporado de outros sites",paragraphs:["Os artigos deste site podem incluir conteúdos incorporados (por exemplo, vídeos, imagens, artigos etc.). O conteúdo incorporado de outros sites se comporta exatamente da mesma forma como se o visitante tivesse acessado diretamente esses sites.","Esses sites podem coletar dados sobre você, utilizar cookies, incorporar rastreamento adicional de terceiros e monitorar sua interação com esse conteúdo incorporado, incluindo o rastreamento de sua interação caso você possua uma conta e esteja conectado ao respectivo site."]},{title:"Com quem compartilhamos seus dados",paragraphs:["Texto sugerido: Se você solicitar a redefinição de senha, seu endereço IP será incluído no e-mail de redefinição."]},{title:"Por quanto tempo retemos seus dados",paragraphs:["Se você deixar um comentário, o comentário e seus metadados serão armazenados por tempo indeterminado. Isso permite reconhecer e aprovar automaticamente comentários subsequentes, sem a necessidade de mantê-los em uma fila de moderação.","Para usuários que se registrarem em nosso site (se houver), também armazenamos as informações pessoais fornecidas em seu perfil de usuário. Todos os usuários podem visualizar, editar ou excluir suas informações pessoais a qualquer momento (exceto o nome de usuário). Os administradores do site também podem visualizar e editar essas informações."]},{title:"Quais são os seus direitos sobre seus dados",paragraphs:["Se você possui uma conta neste site ou deixou comentários, pode solicitar o recebimento de um arquivo exportado contendo os dados pessoais que mantemos sobre você, incluindo quaisquer dados que tenha fornecido.","Você também pode solicitar a exclusão de quaisquer dados pessoais que mantemos sobre você. Isso não inclui dados que somos obrigados a manter para fins administrativos, legais ou de segurança."]},{title:"Para onde seus dados são enviados",paragraphs:["Os comentários dos visitantes podem ser verificados por meio de um serviço automatizado de detecção de spam."]}];function n(){return e.jsxs("div",{className:"min-h-screen bg-[#090604]",children:[e.jsx(s,{title:"Política de Privacidade",description:"Política de Privacidade da DRV Certificações sobre tratamento de dados enviados por formulários, WhatsApp e canais comerciais.",path:"/politica-privacidade",keywords:["política de privacidade","DRV Certificações","LGPD"]}),e.jsx(i,{}),e.jsx("main",{className:"section-pad pt-40 md:pt-44",children:e.jsxs("div",{className:"container max-w-4xl",children:[e.jsx("p",{className:"section-kicker",children:"Privacidade"}),e.jsx("h1",{className:"section-title mt-3",children:"Política de Privacidade"}),e.jsx("div",{className:"mt-8 space-y-10 text-lg leading-relaxed text-slate-700",children:d.map(o=>e.jsxs("section",{children:[e.jsx("h2",{className:"text-2xl font-black text-[#102A43]",children:o.title}),o.paragraphs.map(a=>e.jsx("p",{className:"mt-3",children:a},a))]},o.title))})]})}),e.jsx(r,{})]})}export{n as default};
